# Examples are the matn's where it prints one (marked own=True), else the shortest school phrase that shows the governor.
def P(s, w, re, nt=None, own=False):
    d = {'s': s, 'w': w, 're': re}
    if nt: d['not'] = nt
    if own: d['own'] = True
    return d

